const fileItem = $('Extraire texte').first();
let transcription = fileItem.json.data || fileItem.json.text || '';

if (!transcription || transcription.startsWith('PK')) {
  const dlItem = $('T\u00e9l\u00e9charger transcription').first();
  if (dlItem.binary && dlItem.binary.data) {
    transcription = Buffer.from(dlItem.binary.data.data, 'base64').toString('utf-8');
  } else {
    transcription = dlItem.json.data || dlItem.json.text || JSON.stringify(dlItem.json);
  }
}

const transcriptIdx = transcription.indexOf('Transcription');
if (transcriptIdx > 0) {
  const afterTranscript = transcription.substring(transcriptIdx);
  const timeIdx = afterTranscript.indexOf('00:00:00');
  if (timeIdx > 0) {
    transcription = afterTranscript.substring(timeIdx);
  }
}

const clients = $('R\u00e9cup\u00e9rer liste clients').all().map(item => ({
  nom: item.json['Nom client'],
  domaine: item.json['Domaine email'],
  dossierId: item.json['Dossier Drive ID']
}));
const fichierOriginalId = $('D\u00e9tecter nouvelle transcription').first().json.id;
const fichierOriginalNom = $('D\u00e9tecter nouvelle transcription').first().json.name;

return [{
  json: {
    transcription,
    clients: JSON.stringify(clients),
    fichierOriginalId,
    fichierOriginalNom
  }
}];

const toArray = (v) => Array.isArray(v) ? v : (typeof v === 'string' && v ? [v] : []);

const item = $input.first();
const raw = item.json.text || item.json.output;
let analyse;
if (typeof raw === 'string') {
  const cleaned = raw.replace(/```json\n?/g, '').replace(/```/g, '').trim();
  analyse = JSON.parse(cleaned);
} else {
  analyse = raw;
}

const client = analyse.client || 'Inconnu';
const contexte = analyse.contexte || '';
const langue = analyse.langue || 'fr';
const decisionsCles = toArray(analyse.decisions_cles);
const prochainesEtapes = toArray(analyse.prochaines_etapes);
const participants = (analyse.participants || []).filter(p =>
  p.nom && p.nom.toLowerCase().indexOf('alex') === -1
);

const isFr = langue === 'fr';
const lblDecisions = isFr ? 'D\u00e9cisions cl\u00e9s valid\u00e9es' : 'Key Strategic Pillars Validated';
const lblNextSteps = isFr ? 'Prochaines \u00e9tapes imm\u00e9diates' : 'Immediate Next Steps';
const lblGreeting = isFr ? 'Bonjour' : 'Hi';
const lblClosing = isFr ? 'Cordialement,' : 'Best regards,';
const lblFollowing = isFr ? 'Suite \u00e0 notre derni\u00e8re r\u00e9union' : 'Following our last discussion';

return participants.map(p => {
  const actions = toArray(p.actions);

  // Filter prochaines_etapes relevant to this participant
  const etapesParticipant = prochainesEtapes.filter(e =>
    e.responsable && e.responsable.toLowerCase().includes(p.nom.split(' ')[0].toLowerCase())
  );

  const html = `<div style="font-family: Helvetica, Arial, sans-serif; font-size: 12pt; color: #333; line-height: 1.6; max-width: 600px;">
  <p>${lblGreeting},</p>

  <p>${lblFollowing}. ${contexte}</p>

  <p style="font-weight: bold; text-decoration: underline; margin-top: 20px;">${lblDecisions}</p>
  <ul style="padding-left: 24px;">
    ${decisionsCles.map(d => '<li style="margin-bottom: 6px;">' + (d.point || d) + (d.detail ? ' : ' + d.detail : '') + (d.tbc ? ' <strong>(TBC)</strong>' : '') + '</li>').join('\n    ')}
  </ul>

  <p style="font-weight: bold; text-decoration: underline; margin-top: 20px;">${lblNextSteps}</p>
  <ul style="padding-left: 24px;">
    ${actions.map(a => '<li style="margin-bottom: 6px;">' + a + '</li>').join('\n    ')}
    ${etapesParticipant.map(e => '<li style="margin-bottom: 6px;">' + e.action + (e.echeance ? ' (' + e.echeance + ')' : '') + '</li>').join('\n    ')}
